// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;
    Receiver r;

    function setUp() public { 
        c = new EBU();
        r = new Receiver();
    }

    // fuzzed params: from (actor), caddress (we will supply receiver address), _tos array length and values and v values
    // We cannot fuzz address of callee because EOAs always succeed; deploy Receiver to record calls and always succeed.
    function testFuzz_property(address from, address anyAddr, address to1, uint256 v1, address to2, uint256 v2, bool useTwo) public {
        // Build _tos and v arrays with at least one element (admissible domain requires _tos.length>0)
        address[] memory tos;
        uint[] memory vals;
        if (useTwo) {
            tos = new address[](2);
            vals = new uint[](2);
            // put fuzzed addresses in
            tos[0] = to1;
            tos[1] = to2;
            vals[0] = v1;
            vals[1] = v2;
            // keep wide: no assumptions
        } else {
            tos = new address[](1);
            vals = new uint[](1);
            tos[0] = to1;
            vals[0] = v1;
        }

        // Ensure the callee is our recording helper; use its address as caddress
        address caddress = address(r);

        // We call c.transfer and observe whether it reverts. The correct contract should never revert for any non-empty array.
        bool ok;
        try c.transfer(from, caddress, tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal rule: for every admissible input (tos.length > 0) the reference C completes successfully.
        // So assertTrue(ok) — this will hold on the reference implementation for all fuzz inputs, and fail on the mutant
        // which uses i <= _tos.length and thus can revert when tos.length > 0.
        assertTrue(ok);
    }
}

// Receiver records calls made by C. It implements the exact signature transferFrom(address,address,uint256)
// so that ABI decoding happens and the call behaves like a real contract. It simply records the last call
// and returns true (via low-level call success) by not reverting.
contract Receiver {
    event Called(address from, address to, uint256 v);
    function transferFrom(address from, address to, uint256 v) external {
        emit Called(from, to, v);
    }
}
